R=Path(__file__).resolve().parent;O=R/'results';s=pd.read_csv(O/'summary.csv');d=pd.read_csv(O/'paired_deltas.csv');t=pd.read_csv(O/'selected_thresholds.csv')
methods=['control','always_nn','similarity_gate'];names=['Control','Always NN','Cosine gate'];colors=['#778397','#258c77','#8557af']
