 q=s[(s.cohort=='all')&(s.dimension=='overall')&(s.policy==pol)].set_index('method').loc[methods];v=q.f1.to_numpy()*100
 ax.plot(np.arange(3),v,color='#d8dee7',zorder=1);ax.scatter(np.arange(3),v,c=colors,s=85,zorder=2);ax.set_xticks(np.arange(3));ax.set_xticklabels(names);ax.set_ylim(65,90);ax.set_title(title,fontsize=12);ax.set_ylabel('Macro test F1 (%)');ax.spines['top'].set_visible(False);ax.spines['right'].set_visible(False)
